<script setup lang="ts">
import { computed, defineAsyncComponent, ref } from 'vue'
import MemoMarkdown from '../memos/MemoMarkdown.vue'
import type { PlanRecord, PlanUser } from './types'
import type { AiConversation, AiItemChanges, AiPlanDraft, AiPlanItem } from './ai'
import { selectionWithStages } from './ai'
const MarkdownEditor=defineAsyncComponent(()=>import('../MarkdownEditor.vue'))
const props=defineProps<{draft:AiPlanDraft;currentPlan:AiConversation['current_plan'];record:PlanRecord;users:PlanUser[];selected:string[];edits:Record<string,AiItemChanges>;disabled?:boolean;confirming?:boolean}>()
const emit=defineEmits<{select:[ids:string[]];edit:[id:string,changes:AiItemChanges]}>()
const editing=ref('')
const operation=(item:AiPlanItem)=>item.operation??'create'
const kind=(item:AiPlanItem)=>({plan:'计划',stage:'阶段',task:'任务'})[item.kind]
const verb=(item:AiPlanItem)=>({create:'新增',update:'修改',delete:'移除'})[operation(item)]
const selectedItems=computed(()=>selectionWithStages(props.draft,props.selected,props.edits))
const chosen=computed(()=>new Set(selectedItems.value.map(item=>item.id)))
const choices=computed(()=>props.confirming?selectedItems.value:props.draft.items)
function choose(item:AiPlanItem,checked:boolean){emit('select',checked?[...props.selected,item.id]:props.selected.filter(id=>id!==item.id))}
function selectAll(){emit('select',props.draft.items.filter(item=>!item.adopted&&!item.blocked_reason&&operation(item)!=='delete').map(item=>item.id))}
function after(item:AiPlanItem):AiItemChanges{return {...(item.after??{title:item.title,body_markdown:item.body_markdown,stage_key:item.stage_key,position:item.position,assignee_ids:item.assignee_ids,due_date:item.due_date,target_date:item.target_date,open_questions_markdown:item.open_questions_markdown}),...props.edits[item.id]}}
function original(item:AiPlanItem):AiItemChanges{const current=item.kind==='plan'?props.currentPlan?.record:item.kind==='stage'?props.currentPlan?.stages.find(value=>value.id===item.target_id):props.currentPlan?.tasks.find(value=>value.id===item.target_id);return current?{...current,...('stage_id' in current?{stage_key:String(current.stage_id)}:{})}:{} as AiItemChanges}
function values(item:AiPlanItem):AiItemChanges{return {...original(item),...after(item)}}
function before(item:AiPlanItem,key:string){return Object.hasOwn(item.before??{},key)?item.before?.[key]:original(item)[key as keyof AiItemChanges]}
function field(item:AiPlanItem,key:keyof AiItemChanges,value:unknown){emit('edit',item.id,{...props.edits[item.id],[key]:value})}
function member(id:string){return props.users.find(user=>user.id===id)?.display_name??'原成员'}
const fields:Record<string,string>={title:'名称',body_markdown:'内容',target_date:'目标日期',open_questions_markdown:'待解决的问题',stage_key:'所属阶段',stage_id:'所属阶段',position:'排列顺序',assignee_ids:'负责人',due_date:'任务日期'}
function display(key:string,value:unknown):string{if(value===null||value===undefined||value==='')return '未填写';if(key==='assignee_ids')return (value as string[]).map(member).join('、')||'待分配';if(key==='position')return String(Number(value)+1);if(key==='stage_key'||key==='stage_id')return stageOptions.value.find(stage=>stage.id===value)?.title??'原阶段';return String(value)}
function diffFields(item:AiPlanItem){return [...new Set([...(item.changed_fields??Object.keys(item.after??{})),...Object.keys(props.edits[item.id]??{})])].filter(key=>key in fields)}
const stageOptions=computed(()=>[...(props.currentPlan?.stages??[]).filter(stage=>!stage.deleted).map(stage=>({id:stage.id,title:stage.title})),...props.draft.items.filter(item=>item.kind==='stage'&&operation(item)==='create').map(item=>({id:item.id,title:String(after(item).title??item.title)}))])
type ReadingItem={id:string;title:string;body_markdown:string;position:number;stage_id?:string;completed?:boolean;assignee_ids?:string[];due_date?:string|null}
const reading=computed(()=>{
 const plan={title:props.currentPlan?.record.title??props.record.title,body_markdown:props.currentPlan?.record.body_markdown??'',open_questions_markdown:props.currentPlan?.record.open_questions_markdown??'',target_date:props.currentPlan?.record.target_date??null}
 const stages:ReadingItem[]=(props.currentPlan?.stages??[]).filter(item=>!item.deleted).map(item=>({...item,body_markdown:item.body_markdown??''}))
 const tasks:ReadingItem[]=(props.currentPlan?.tasks??[]).filter(item=>!item.deleted).map(item=>({...item}))
 for(const item of selectedItems.value){const change=after(item),id=item.target_id??item.entity_id??item.id;if(item.kind==='plan'){if(operation(item)!=='delete')Object.assign(plan,change);continue}const list=item.kind==='stage'?stages:tasks,index=list.findIndex(value=>value.id===id);if(operation(item)==='delete'){if(index>=0)list.splice(index,1);continue}const value={...(index>=0?list[index]:{id,title:item.title,body_markdown:'',position:list.length,completed:false}),...change,...(item.kind==='task'&&change.stage_key!==undefined?{stage_id:props.draft.items.find(stage=>stage.kind==='stage'&&stage.id===change.stage_key)?.entity_id??change.stage_key??undefined}:{})} as ReadingItem;if(index>=0)list[index]=value;else list.push(value)}
 const order=(a:ReadingItem,b:ReadingItem)=>a.position-b.position||a.id.localeCompare(b.id)
 return {plan,stages:stages.sort(order),tasks:tasks.sort(order)}
})
</script>
<template>
 <p v-if="draft.legacy" class="ai-notice">历史草案仅保留当时的阶段与任务，可按原内容采用。它不含完整总说明；继续讨论可生成新版可编辑方案。</p><section class="ai-full-plan" aria-label="完整方案预览"><p class="ai-meta">{{ confirming?'采用后的完整方案':'完整方案 · 随下方选择即时预览' }}</p><h3>{{ reading.plan.title }}</h3><p v-if="reading.plan.target_date" class="ai-meta">目标日期 · {{ reading.plan.target_date }}</p><MemoMarkdown v-if="reading.plan.body_markdown" :markdown="reading.plan.body_markdown"/><section v-for="(stage,index) in reading.stages" :key="stage.id" class="ai-reading-stage"><h4><span>{{ index+1 }}</span>{{ stage.title }}</h4><MemoMarkdown v-if="stage.body_markdown" :markdown="stage.body_markdown"/><article v-for="task in reading.tasks.filter(item=>item.stage_id===stage.id)" :key="task.id" class="ai-reading-task"><h5>{{ task.completed?'✓ ':'' }}{{ task.title }}</h5><p class="ai-meta">{{ task.assignee_ids?.length?task.assignee_ids.map(member).join('、'):'负责人待定' }} · {{ task.due_date??'日期待定' }}{{ task.completed?' · 已完成':'' }}</p><MemoMarkdown v-if="task.body_markdown" :markdown="task.body_markdown"/></article></section><section v-if="reading.plan.open_questions_markdown" class="ai-reading-questions"><h4>待解决的问题</h4><MemoMarkdown :markdown="reading.plan.open_questions_markdown"/></section><p v-if="!reading.stages.length&&!reading.plan.body_markdown" class="ai-meta">勾选下方内容，组成这次方案。</p></section>
 <section class="ai-revisions" aria-label="方案修订"><div class="ai-revision-heading"><h3>{{ confirming?'本次将采用':'选择本次修订' }}</h3><div v-if="!confirming" class="ai-select-actions"><button type="button" class="wp-link" :disabled="disabled" @click="selectAll">全选可用内容</button><button type="button" class="wp-link" :disabled="disabled" @click="emit('select',[])">清空选择</button></div></div><p v-if="!confirming" class="ai-meta">可先编辑，再逐项采用；编辑仅在确认采用时保存。移除建议需主动勾选。</p>
 <article v-for="item in choices" :key="item.id" class="ai-revision" :class="{'is-selected':chosen.has(item.id),'is-blocked':!!item.blocked_reason}"><div class="ai-revision-top"><label class="ai-check"><input v-if="!confirming" type="checkbox" :checked="item.adopted||chosen.has(item.id)" :disabled="disabled||item.adopted||!!item.blocked_reason" :aria-label="'采用'+item.title" @change="choose(item,($event.target as HTMLInputElement).checked)"><span><small>{{ item.adopted?'已采用':verb(item)+kind(item) }}</small><strong>{{ values(item).title??item.title }}</strong></span></label><button v-if="!confirming&&!draft.legacy&&!item.adopted&&!item.blocked_reason&&operation(item)!=='delete'" type="button" class="wp-link" :disabled="disabled" @click="editing=editing===item.id?'':item.id">{{ editing===item.id?'收起编辑':'编辑内容' }}</button></div><p v-if="item.blocked_reason" class="ai-error">{{ item.blocked_reason==='creator_required'?'需创建者处理：请返回原任务申请删除。':item.blocked_reason==='task_completed'?'任务已完成，保留完成记录。':'此项暂不能采用，请核对原计划。' }}</p>
 <div v-if="editing===item.id&&!confirming" class="ai-revision-editor"><label class="wp-field">名称<input :value="values(item).title??item.title" maxlength="200" :disabled="disabled" @input="field(item,'title',($event.target as HTMLInputElement).value)"></label><div class="wp-field"><span>方案内容</span><MarkdownEditor :model-value="String(values(item).body_markdown??item.body_markdown)" :disabled="disabled" @update:model-value="field(item,'body_markdown',$event)"/></div><template v-if="item.kind==='task'"><label class="wp-field">所属阶段<select :value="values(item).stage_key??item.stage_key" :disabled="disabled" @change="field(item,'stage_key',($event.target as HTMLSelectElement).value)"><option v-for="stage in stageOptions" :key="stage.id" :value="stage.id">{{ stage.title }}</option></select></label><fieldset class="wp-assignees" :disabled="disabled"><legend>负责人</legend><label v-for="user in users.filter(user=>user.assignable!==false||(values(item).assignee_ids??item.assignee_ids).includes(user.id))" :key="user.id"><input type="checkbox" :checked="(values(item).assignee_ids??item.assignee_ids).includes(user.id)" @change="field(item,'assignee_ids',($event.target as HTMLInputElement).checked?[...(values(item).assignee_ids??item.assignee_ids),user.id]:(values(item).assignee_ids??item.assignee_ids).filter(id=>id!==user.id))">{{ user.display_name }}</label></fieldset><label class="wp-field">任务日期<input type="date" :value="values(item).due_date??''" :disabled="disabled" @input="field(item,'due_date',($event.target as HTMLInputElement).value||null)"></label></template><label v-if="item.kind!=='plan'" class="wp-field">排列顺序<input type="number" min="1" :value="Number(values(item).position??0)+1" :disabled="disabled" @input="field(item,'position',Math.max(0,Number(($event.target as HTMLInputElement).value)-1))"></label><template v-if="item.kind==='plan'"><label class="wp-field">目标日期<input type="date" :value="values(item).target_date??''" :disabled="disabled" @input="field(item,'target_date',($event.target as HTMLInputElement).value||null)"></label><label class="wp-field">待解决的问题<textarea :value="values(item).open_questions_markdown??''" :disabled="disabled" @input="field(item,'open_questions_markdown',($event.target as HTMLTextAreaElement).value)"></textarea></label></template><p class="ai-meta">这些编辑将在确认采用时保存。</p></div>
 <div v-if="operation(item)==='create'" class="ai-change-content"><MemoMarkdown v-if="confirming&&after(item).body_markdown" :markdown="String(after(item).body_markdown)"/><details v-else-if="after(item).body_markdown"><summary>查看建议内容</summary><MemoMarkdown :markdown="String(after(item).body_markdown)"/></details></div><div v-else class="ai-change-diff"><div><small>修改前</small><template v-for="key in diffFields(item)" :key="key"><p class="ai-diff-label">{{ fields[key] }}</p><p class="ai-prose">{{ display(key,before(item,key)) }}</p></template><p v-if="operation(item)==='delete'" class="ai-prose">{{ item.before?.body_markdown??item.body_markdown }}</p></div><div><small>{{ operation(item)==='delete'?'采用后':'修改后' }}</small><p v-if="operation(item)==='delete'" class="ai-prose">从计划移除</p><template v-else v-for="key in diffFields(item)" :key="key"><p class="ai-diff-label">{{ fields[key] }}</p><p class="ai-prose">{{ display(key,after(item)[key as keyof AiItemChanges]) }}</p></template></div></div>
 </article></section>
</template>
